// For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life. — John 3:16 (KJV)

//! Ephemeral row 694 parent attribution. Production source is detached main 2b21816e.
//! This is the exact 699 written-instance fixture, measured on interpreter and LLVM only.

use haskelujah_span_chirho::SourceMapChirho;
use haskelujah_test_harness_chirho::native_chirho::{
    NativeBackendChirho, native_round_trip_chirho,
};

const WRITTEN_PARAMETRIC_SHOW_CHIRHO: &str = r#"-- For God so loved the world, that he gave his only begotten Son, that whosoever believeth in him should not perish, but have everlasting life. — John 3:16 (KJV)
module Main where
newtype BoxChirho aChirho = BoxChirho aChirho
instance Show aChirho => Show (BoxChirho aChirho) where
  show (BoxChirho xChirho) = show xChirho
main :: IO ()
main = print (BoxChirho (7 :: Int))
"#;

#[test]
fn written_box_interpreter_matches_ghc_chirho() {
    let (_, machine_chirho) = haskelujah_driver::eval_source_with_machine_chirho(
        WRITTEN_PARAMETRIC_SHOW_CHIRHO,
        &mut SourceMapChirho::new_chirho(),
        "WrittenParametricShowChirho.hs",
        None,
    )
    .expect("written instance should compile on the parent");
    assert_eq!(machine_chirho.io_output_chirho, "7\n");
}

#[test]
fn written_box_llvm_matches_ghc_chirho() {
    let outcome_chirho = native_round_trip_chirho(
        WRITTEN_PARAMETRIC_SHOW_CHIRHO,
        NativeBackendChirho::LlvmChirho,
        "",
    );
    assert_eq!(outcome_chirho, Ok((0, "7\n".to_string())));
}
